/**
 * Assignment has its own permission because a member may reassign work they
 * do not otherwise own. Un-assigning publishes `issue.unassigned` instead,
 * since `issue.assigned` carries a non-null assignee by contract; clearing an
 * assignee that is already empty changes nothing and publishes nothing.
 */
export async function assignIssue(
  actor: Actor,
  input: AssignIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:assign", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  if (input.assigneeId === null) {
    const previousAssigneeId = before.assigneeId;
    if (previousAssigneeId === null) return before;

    const after = await issueRepo.setIssueAssignee(
      input.orgId,
      input.issueId,
      null,
    );

    await emit("issue.unassigned", {
      ...actorEnvelope(actor),
      issueId: after.id,
      projectId: after.projectId,
      previousAssigneeId,
    });

    return after;
  }

  const after = await issueRepo.setIssueAssignee(
    input.orgId,
    input.issueId,
    input.assigneeId,
  );

  await emit("issue.assigned", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    previousAssigneeId: before.assigneeId,
    assigneeId: input.assigneeId,
  });

  return after;
}

/**
 * Releases every live issue held by `userId`, publishing one
 * `issue.unassigned` per issue with `actor` as the actor. Used when a member
 * leaves the organization; it is a consequence of that removal rather than an
 * assignment decision, so it carries no `issue:assign` check of its own.
 */
export async function unassignIssuesForUser(
  actor: Actor,
  userId: UserId,
): Promise<readonly Issue[]> {
  const released = await issueRepo.clearAssigneeForUser(actor.orgId, userId);

  for (const issue of released) {
    await emit("issue.unassigned", {
      ...actorEnvelope(actor),
      issueId: issue.id,
      projectId: issue.projectId,
      previousAssigneeId: userId,
    });
  }

  return released;
}

