  // issue.unassigned is a subscribable event type.
  it("accepts issue.unassigned as a webhook event type", () => {
    const parsed = createWebhookSchema.safeParse({
      orgId: tenant.org.id,
      url: "https://example.test/hook",
      eventTypes: ["issue.unassigned"],
    });

    expect(parsed.success).toBe(true);
  });

  // Subscribed + enabled endpoints get one delivery carrying the payload as JSON.
  it("delivers issue.unassigned only to subscribed, enabled endpoints", async () => {
    const subscribed = await webhookRepo.insertEndpoint(
      {
        orgId: tenant.org.id,
        url: "https://example.test/subscribed",
        eventTypes: ["issue.unassigned"],
      },
      "secret-subscribed",
    );
    const other = await webhookRepo.insertEndpoint(
      {
        orgId: tenant.org.id,
        url: "https://example.test/other",
        eventTypes: ["issue.created"],
      },
      "secret-other",
    );
    const disabled = await webhookRepo.insertEndpoint(
      {
        orgId: tenant.org.id,
        url: "https://example.test/disabled",
        eventTypes: ["issue.unassigned"],
      },
      "secret-disabled",
    );
    await webhookRepo.updateEndpoint({
      orgId: tenant.org.id,
      webhookId: disabled.id as never,
      enabled: false,
    });

    const payload = {
      orgId: tenant.org.id,
      actorId: tenant.userIds.admin,
      occurredAt: tenant.org.createdAt,
      issueId: "iss-webhook-1" as IssueId,
      projectId: tenant.project.id,
      previousAssigneeId: tenant.userIds.member,
    };
    await emit("issue.unassigned", payload);

    const delivered = deliveriesFor(subscribed.id);
    expect(delivered).toHaveLength(1);
    expect(delivered[0]?.eventType).toBe("issue.unassigned");
    expect(JSON.parse(delivered[0]?.payload ?? "null")).toEqual(payload);

    expect(deliveriesFor(other.id)).toHaveLength(0);
    expect(deliveriesFor(disabled.id)).toHaveLength(0);
  });
});
