/**
 * Outgoing webhooks: which endpoints receive which domain events.
 *
 * Owner C implements `@/server/services/webhook-service`.
 */
import { and, eq } from "drizzle-orm";
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { emit } from "@/lib/event-bus";
import { createWebhookSchema } from "@/schemas/webhook";
import { getDb, webhookDeliveries } from "@/server/db";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { registerWebhookListeners } from "@/server/services/webhook-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IssueId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("webhooks", "growth");
  detach = registerWebhookListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

function deliveriesFor(endpointId: string) {
  return getDb()
    .select()
    .from(webhookDeliveries)
    .where(
      and(
        eq(webhookDeliveries.orgId, tenant.org.id),
        eq(webhookDeliveries.endpointId, endpointId),
      ),
    )
    .all();
}

describe("services/webhook-service", () => {
  // issue.unassigned is a subscribable event type.
  it("accepts issue.unassigned as a webhook event type", () => {
    const parsed = createWebhookSchema.safeParse({
      orgId: tenant.org.id,
      url: "https://example.test/hook",
      eventTypes: ["issue.unassigned"],
    });

    expect(parsed.success).toBe(true);
  });

  // Subscribed + enabled endpoints get one delivery carrying the payload as JSON.
  it("delivers issue.unassigned only to subscribed, enabled endpoints", async () => {
    const subscribed = await webhookRepo.insertEndpoint(
      {
        orgId: tenant.org.id,
        url: "https://example.test/subscribed",
        eventTypes: ["issue.unassigned"],
      },
      "secret-subscribed",
    );
    const other = await webhookRepo.insertEndpoint(
      {
        orgId: tenant.org.id,
        url: "https://example.test/other",
        eventTypes: ["issue.created"],
      },
      "secret-other",
    );
    const disabled = await webhookRepo.insertEndpoint(
      {
        orgId: tenant.org.id,
        url: "https://example.test/disabled",
        eventTypes: ["issue.unassigned"],
      },
      "secret-disabled",
    );
    await webhookRepo.updateEndpoint({
      orgId: tenant.org.id,
      webhookId: disabled.id as never,
      enabled: false,
    });

    const payload = {
      orgId: tenant.org.id,
      actorId: tenant.userIds.admin,
      occurredAt: tenant.org.createdAt,
      issueId: "iss-webhook-1" as IssueId,
      projectId: tenant.project.id,
      previousAssigneeId: tenant.userIds.member,
    };
    await emit("issue.unassigned", payload);

    const delivered = deliveriesFor(subscribed.id);
    expect(delivered).toHaveLength(1);
    expect(delivered[0]?.eventType).toBe("issue.unassigned");
    expect(JSON.parse(delivered[0]?.payload ?? "null")).toEqual(payload);

    expect(deliveriesFor(other.id)).toHaveLength(0);
    expect(deliveriesFor(disabled.id)).toHaveLength(0);
  });
});

